import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const html=fs.readFileSync(new URL('../arcade.html',import.meta.url),'utf8');
const source=html.match(/<script>([\s\S]*?)<\/script>/)[1];
function engine(){const context=vm.createContext({});vm.runInContext(source.split('const $=')[0]+'\nglobalThis.Game=Game;',context);return new context.Game(()=>0.42);}
const cells=g=>g.board.flat().filter(Boolean).length;
test('seven-bag provides every piece once and three previews remain available',()=>{const g=engine();const types=[];for(let i=0;i<14;i++){types.push(g.active.type);assert.ok(g.queue.length>=3);g.spawn();}assert.equal(new Set(types.slice(0,7)).size,7);assert.equal(new Set(types.slice(7)).size,7);});
test('movement rejects walls, floor and occupied cells',()=>{const g=engine();g.spawn('O');while(g.move(-1,0)){}assert.equal(g.active.x,0);assert.equal(g.move(-1,0),false);while(g.move(1,0)){}assert.equal(g.active.x,8);g.board[3][8]='I';assert.equal(g.move(0,1),true);assert.equal(g.move(0,1),false);g.board[3][8]=null;while(g.move(0,1)){}assert.equal(g.active.y,18);assert.equal(g.move(0,1),false);});
test('rotations round trip, kick off walls, and reject a blocked rotation',()=>{const g=engine();g.spawn('T');const original=JSON.stringify(g.active.m);for(let i=0;i<4;i++)assert.equal(g.rotate(),true);assert.equal(JSON.stringify(g.active.m),original);g.rotate(1);g.rotate(-1);assert.equal(JSON.stringify(g.active.m),original);g.spawn('I');g.rotate();while(g.move(-1,0)){}assert.equal(g.rotate(),true);assert.ok(g.valid(g.active.m,g.active.x,g.active.y));g.board=Array.from({length:20},()=>Array(10).fill('Z'));assert.equal(g.rotate(),false);});
test('ghost and hard drop agree, award distance points and lock exactly four cells',()=>{const g=engine();g.spawn('O');const y=g.ghostY();assert.equal(y,18);assert.equal(g.active.y,0);g.hardDrop();assert.equal(cells(g),4);assert.equal(g.score,36);assert.equal(g.board[19][4],'O');assert.equal(g.board[19][5],'O');});
test('hold is limited to once per lock and resets swapped orientation',()=>{const g=engine();g.spawn('T');g.rotate();const next=g.queue[0];assert.equal(g.hold(),true);assert.equal(g.held,'T');assert.equal(g.active.type,next);assert.equal(g.hold(),false);g.hardDrop();assert.equal(g.holdUsed,false);assert.equal(g.hold(),true);assert.equal(g.active.type,'T');assert.equal(JSON.stringify(g.active.m),JSON.stringify([[0,1,0],[1,1,1],[0,0,0]]));assert.equal(g.active.y,0);});
test('four lines clear simultaneously with scoring, combos and level progression',()=>{const g=engine();function well(){g.board=Array.from({length:20},(_,y)=>Array.from({length:10},(_,x)=>y>=16&&x!==5?'J':null));g.spawn('I');g.rotate();}well();g.lines=8;g.active.y=g.ghostY();assert.equal(g.lock(),4);assert.equal(g.lines,12);assert.equal(g.level,2);assert.equal(g.score,800);assert.equal(cells(g),0);well();g.active.y=g.ghostY();g.lock();assert.equal(g.score,2500);assert.equal(g.combo,1);g.hardDrop();assert.equal(g.combo,-1);});
test('clearing one row shifts cells above it down',()=>{const g=engine();g.board[19]=Array(10).fill('J');g.board[19][4]=g.board[19][5]=null;g.board[17][0]='T';g.spawn('O');g.active.y=g.ghostY();assert.equal(g.lock(),1);assert.equal(g.score,100);assert.equal(g.board[18][0],'T');assert.equal(g.board[19][4],'O');assert.equal(g.board[0].every(v=>v===null),true);});
test('blocked spawn and hold end the game; reset restores a clean run',()=>{const g=engine();g.board[0].fill('Z');g.spawn('O');assert.equal(g.over,true);assert.equal(g.move(1,0),false);assert.equal(g.rotate(),false);assert.equal(g.hold(),false);g.reset();assert.equal(g.over,false);assert.equal(g.score,0);assert.equal(g.lines,0);assert.equal(cells(g),0);assert.equal(g.held,null);g.held='O';g.board[0].fill('Z');g.hold();assert.equal(g.over,true);});
function ui(){const elements=new Map(),events={};const noop=()=>{};const context2d=new Proxy({}, {get:(o,k)=>o[k]||noop,set:(o,k,v)=>(o[k]=v,true)});function element(id){if(!elements.has(id))elements.set(id,{id,textContent:'',hidden:false,disabled:false,style:{},firstChild:{textContent:''},events:{},setAttribute:noop,getContext:()=>context2d,addEventListener(name,fn){this.events[name]=fn;},blur:noop});return elements.get(id);}const sandbox={document:{getElementById:element,querySelectorAll:()=>[],addEventListener:(k,f)=>events[k]=f,hidden:false},window:{addEventListener:noop,confirm:()=>true},localStorage:{getItem:()=>{throw Error('blocked');},setItem:()=>{throw Error('blocked');}},requestAnimationFrame:noop};vm.createContext(sandbox);vm.runInContext(source,sandbox);return {run:s=>vm.runInContext(s,sandbox),element,events};}
test('UI starts, moves, pauses simulation, resumes, holds and restarts without storage',()=>{const u=ui();assert.equal(u.run('mode'),'ready');u.element('play').events.click();assert.equal(u.run('mode'),'playing');assert.equal(u.element('overlay').hidden,true);u.run("act('left')");assert.equal(u.run('game.active.x'),2);u.run("act('hold')");assert.equal(u.element('touch-hold').disabled,true);u.element('pause').events.click();assert.equal(u.run('mode'),'paused');const x=u.run('game.active.x');u.run("act('right');frame(10000)");assert.equal(u.run('game.active.x'),x);u.element('play').events.click();assert.equal(u.run('mode'),'playing');u.run("act('drop')");assert.ok(u.run('game.score')>0);u.element('restart').events.click();assert.equal(u.run('mode'),'playing');assert.equal(u.run('game.score'),0);});
test('gravity locks a grounded piece, game over displays score and restart recovers',()=>{const u=ui();u.run("start();game.spawn('O');game.active.y=18");for(let t=50;t<=550;t+=50)u.run(`frame(${t})`);assert.equal(u.run('game.board.flat().filter(Boolean).length'),4);u.run("game.score=321;game.board[0].fill('Z');game.spawn('O');finish(0);update()");assert.equal(u.run('mode'),'over');assert.match(u.element('overlay-copy').textContent,/321 points/);assert.equal(u.element('overlay').hidden,false);assert.equal(u.run('best'),321);u.element('play').events.click();assert.equal(u.run('mode'),'playing');assert.equal(u.run('game.over'),false);});
test('keyboard prevents scrolling, suppresses repeated hard drops, and pauses on visibility loss',()=>{const u=ui();u.run('start()');let prevented=false;u.events.keydown({key:' ',target:{tagName:'BODY'},preventDefault(){prevented=true;}});assert.equal(prevented,true);assert.equal(u.run('game.board.flat().filter(Boolean).length'),4);u.events.keydown({key:' ',repeat:true,target:{tagName:'BODY'},preventDefault(){}});assert.equal(u.run('game.board.flat().filter(Boolean).length'),4);u.run('document.hidden=true');u.events.visibilitychange();assert.equal(u.run('mode'),'paused');});

